// @FIGURE_CODE_BEGIN
const W = 800, H = 600;
const draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

let n = 8;
let samplePos = 0.5;

// Main Curve definition (starts bottom left, makes a CCW loop, ends right)
const pathStr = "M 80 480 C 250 480, 350 400, 280 250 C 200 80, 80 250, 220 300 C 350 350, 450 250, 500 100";
const mainCurveNode = document.createElementNS('http://www.w3.org/2000/svg', 'path');
mainCurveNode.setAttribute('d', pathStr);

// Add to defs to ensure getPointAtLength and getTotalLength work natively
const defs = draw.defs();
defs.node.appendChild(mainCurveNode);
const totalLen = mainCurveNode.getTotalLength();

// Static background layer
const bgLayer = draw.group();
bgLayer.path(pathStr).fill('none').stroke({ color: '#2ea3f2', width: 3 });

const dynamicGroup = draw.group();

// Helper to extract a sequence of points along a path segment
function getSubPath(node, startL, endL, steps = 20) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let l = startL + (endL - startL) * (i / steps);
    let p = node.getPointAtLength(l);
    pts.push([p.x, p.y]);
  }
  return pts;
}

// Helper to generate a parallel offset path for dimension lines
function getOffsetPath(node, startL, endL, offset) {
  let pts = [];
  const steps = 15;
  for (let i = 0; i <= steps; i++) {
    let l = startL + (endL - startL) * (i / steps);
    let p = node.getPointAtLength(l);
    let pPrev = node.getPointAtLength(Math.max(0, l - 0.5));
    let pNext = node.getPointAtLength(Math.min(totalLen, l + 0.5));
    let dx = pNext.x - pPrev.x;
    let dy = pNext.y - pPrev.y;
    let dLen = Math.hypot(dx, dy);
    let nx = -dy / dLen;
    let ny = dx / dLen;
    pts.push([p.x + nx * offset, p.y + ny * offset]);
  }
  return pts;
}

// Helper to draw an arc with end arrows and a central label
function drawDimensionArc(group, pts, color, labelText) {
  group.polyline(pts.map(p => p.join(',')).join(' ')).fill('none').stroke({ color: color, width: 1.5 });

  const p0 = pts[0], p1 = pts[1];
  const a0 = Math.atan2(p0[1] - p1[1], p0[0] - p1[0]) * 180 / Math.PI;
  group.polygon('0,0 -10,-4 -10,4').fill(color)
       .translate(p0[0], p0[1]).rotate(a0, p0[0], p0[1]);

  const pn = pts[pts.length - 1], pn1 = pts[pts.length - 2];
  const an = Math.atan2(pn[1] - pn1[1], pn[0] - pn1[0]) * 180 / Math.PI;
  group.polygon('0,0 -10,-4 -10,4').fill(color)
       .translate(pn[0], pn[1]).rotate(an, pn[0], pn[1]);

  const midIdx = Math.floor(pts.length / 2);
  const midP = pts[midIdx];
  group.text(labelText).font({ size: 16, family: 'serif', style: 'italic' })
       .center(midP[0], midP[1])
       .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
}

function updateScene() {
  dynamicGroup.clear();

  // Pick a segment roughly 45% along the path (inside the loop)
  let k = Math.floor(n * 0.45);
  k = Math.max(0, Math.min(n - 1, k));

  let segLen = totalLen / n;
  let startL = k * segLen;
  let endL = (k + 1) * segLen;

  // 1. Draw partition points and selected labels on the main curve
  for (let i = 0; i <= n; i++) {
    let l = i * segLen;
    let p = mainCurveNode.getPointAtLength(l);
    dynamicGroup.circle(9).center(p.x, p.y).fill('#2ea3f2');

    let label = '';
    if (i === 0) label = 'P = P₀';
    else if (i === n) label = 'Q = Pₙ';
    else if (i === k) label = 'Pₖ₋₁';
    else if (i === k + 1) label = 'Pₖ';
    else if (n <= 12 && (i === 1 || i === 2 || i === 3)) label = `P_{${i}}`;
    else if (i === n - 1 && n <= 15) label = 'Pₙ₋₁';

    if (label) {
      let offset = { x: 15, y: 15 };
      if (i === 0) offset = { x: 0, y: 20 };
      if (i === n) offset = { x: 0, y: -25 };
      if (i === k) offset = { x: -25, y: -10 };
      if (i === k + 1) offset = { x: 25, y: 15 };
      if (i > 0 && i < 4) offset = { x: 20, y: 15 };
      if (i === n - 1) offset = { x: 25, y: 0 };

      let finalLabel = label.replace(/_\{(\d+)\}/, (m, d) => 'P' + '₀₁₂₃₄₅₆₇₈₉'[d]);
      dynamicGroup.text(finalLabel)
        .font({ size: 16, family: 'serif', style: 'italic' })
        .center(p.x + offset.x, p.y + offset.y)
        .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
    }
  }

  // 2. Highlight k-th segment
  let kPathPts = getSubPath(mainCurveNode, startL, endL, 20);
  dynamicGroup.polyline(kPathPts.map(p => p.join(',')).join(' '))
    .fill('none').stroke({ color: '#1a75ff', width: 5 });

  // Tick marks bounding the k-th segment
  [startL, endL].forEach(l => {
    let p = mainCurveNode.getPointAtLength(l);
    let pPrev = mainCurveNode.getPointAtLength(Math.max(0, l - 0.5));
    let pNext = mainCurveNode.getPointAtLength(Math.min(totalLen, l + 0.5));
    let dx = pNext.x - pPrev.x, dy = pNext.y - pPrev.y;
    let dLen = Math.hypot(dx, dy);
    let nx = -dy / dLen, ny = dx / dLen;
    dynamicGroup.line(p.x - nx * 10, p.y - ny * 10, p.x + nx * 10, p.y + ny * 10)
      .stroke({ width: 2, color: '#333' });
  });

  // 3. Main curve dimension line for Δs_k
  let dimPts = getOffsetPath(mainCurveNode, startL, endL, 25);
  drawDimensionArc(dynamicGroup, dimPts, '#555', 'Δsₖ');

  // 4. "Mass ΔM_k" label pointing to the main curve segment
  let midL = startL + segLen / 2;
  let midP = mainCurveNode.getPointAtLength(midL);
  dynamicGroup.text('Mass ΔMₖ')
    .font({ size: 18, family: 'serif', style: 'italic' })
    .center(midP.x - 80, midP.y + 60);

  // Arrow pointing from label text to segment center
  let tx = midP.x - 65, ty = midP.y + 45;
  let mx = midP.x - 15, my = midP.y + 10;
  dynamicGroup.path(`M ${tx} ${ty} Q ${tx + 20} ${ty - 10}, ${mx} ${my}`)
    .fill('none').stroke({ width: 1.5, color: '#333' });
  let aAngle = Math.atan2(my - (ty - 10), mx - (tx + 20)) * 180 / Math.PI;
  dynamicGroup.polygon('0,0 -8,-4 -8,4').fill('#333')
    .translate(mx, my).rotate(aAngle, mx, my);

  // 5. Light-orange zoom arrow mapping the sub-arc to the inset
  const insetTargetX = 640, insetTargetY = 380;
  const ax = midP.x + 30, ay = midP.y + 30;
  const bx = insetTargetX - 130, by = insetTargetY - 45;
  const cx_arrow = (ax + bx) / 2 + 40, cy_arrow = Math.max(ay, by) + 100;

  const arrowPath = `M ${ax} ${ay} Q ${cx_arrow} ${cy_arrow}, ${bx} ${by}`;
  dynamicGroup.path(arrowPath).fill('none').stroke({ color: '#e6d3ba', width: 34, linecap: 'round' });
  dynamicGroup.path(arrowPath).fill('none').stroke({ color: '#fdf3e1', width: 30, linecap: 'round' });

  const arrowAngle = Math.atan2(by - cy_arrow, bx - cx_arrow) * 180 / Math.PI;
  dynamicGroup.polygon('0,0 -28,-18 -18,0 -28,18')
    .fill('#fdf3e1')
    .stroke({ color: '#e6d3ba', width: 2 })
    .translate(bx + 10, by)
    .rotate(arrowAngle, bx + 10, by);

  // 6. Magnified inset segment
  const insetScale = 200 / segLen;
  const cX = kPathPts.map(p => p[0]).reduce((a, b) => a + b) / kPathPts.length;
  const cY = kPathPts.map(p => p[1]).reduce((a, b) => a + b) / kPathPts.length;

  const insetPts = kPathPts.map(p => [
    insetTargetX + (p[0] - cX) * insetScale,
    insetTargetY + (p[1] - cY) * insetScale
  ]);

  dynamicGroup.polyline(insetPts.map(p => p.join(',')).join(' '))
    .fill('none').stroke({ color: '#2ea3f2', width: 7 });

  dynamicGroup.circle(14).center(insetPts[0][0], insetPts[0][1]).fill('#2ea3f2');
  dynamicGroup.circle(14).center(insetPts[insetPts.length - 1][0], insetPts[insetPts.length - 1][1]).fill('#2ea3f2');

  dynamicGroup.text('Pₖ₋₁').font({ size: 18, family: 'serif', style: 'italic' })
    .center(insetPts[0][0] - 25, insetPts[0][1] + 25);
  dynamicGroup.text('Pₖ').font({ size: 18, family: 'serif', style: 'italic' })
    .center(insetPts[insetPts.length - 1][0] + 25, insetPts[insetPts.length - 1][1] + 25);

  // Inset dimension line
  let insetDimPts = [];
  for (let i = 0; i < insetPts.length; i++) {
    let p = insetPts[i];
    let pPrev = insetPts[Math.max(0, i - 1)];
    let pNext = insetPts[Math.min(insetPts.length - 1, i + 1)];
    if (i === 0) pPrev = p;
    if (i === insetPts.length - 1) pNext = p;
    let dx = pNext[0] - pPrev[0], dy = pNext[1] - pPrev[1];
    let dLen = Math.hypot(dx, dy);
    let nx = -dy / dLen, ny = dx / dLen;
    insetDimPts.push([p[0] + nx * 45, p[1] + ny * 45]);
  }
  drawDimensionArc(dynamicGroup, insetDimPts, '#555', 'Δsₖ');

  // 7. Dynamic Sample Point (P_k^*)
  let sLen = startL + samplePos * segLen;
  let sPointMain = mainCurveNode.getPointAtLength(sLen);
  let sInsetX = insetTargetX + (sPointMain.x - cX) * insetScale;
  let sInsetY = insetTargetY + (sPointMain.y - cY) * insetScale;

  dynamicGroup.circle(16).center(sInsetX, sInsetY).fill('#f23a2e');
  dynamicGroup.text('Pₖ*(xₖ*, yₖ*, zₖ*)')
    .font({ size: 18, family: 'serif', style: 'italic' })
    .move(sInsetX + 15, sInsetY + 15);

  // 8. Integration Convergence / Formula Box
  let totalSum = 0;
  for (let i = 0; i < n; i++) {
    let l = (i + samplePos) * segLen;
    let p = mainCurveNode.getPointAtLength(l);
    // Arbitrary background density function mapping roughly to (y) bounds
    let density = 1 + (600 - p.y) / 200;
    totalSum += density * segLen;
  }

  // Formula box container
  const boxGroup = dynamicGroup.group().move(80, 500);
  boxGroup.rect(340, 50).fill('#fff').stroke({ color: '#bbb', width: 2 }).radius(4);
  boxGroup.text('ΔMₖ ≈ f(xₖ*, yₖ*, zₖ*) Δsₖ')
    .font({ size: 20, family: 'serif', style: 'italic' })
    .center(170, 25);
  boxGroup.css('cursor', 'pointer')
    .on('mousemove', e => showTooltip('The mass of the k-th segment is estimated by multiplying the density at the sample point by the length of the sub-arc.', e))
    .on('mouseleave', hideTooltip);

  dynamicGroup.text(`Riemann Sum (Total Mass) ≈ ${totalSum.toFixed(1)}`)
    .font({ size: 18, family: 'sans-serif', weight: 'bold' })
    .center(250, 480)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4 });
}

// Interaction Handlers
window.update_numSegments = function(v) {
  n = v;
  updateScene();
};

window.update_samplePos = function(v) {
  samplePos = v;
  updateScene();
};

// --- Step Player ---
const demoSteps = [
  { n: 8, pos: 0.5, txt: "The curve from P to Q is divided into n sub-arcs. We estimate the total mass by approximating the mass of each sub-arc and summing them." },
  { n: 8, pos: 0.8, txt: "Within each segment k, we pick a sample point to evaluate the density function. Slide the sample point position to see it move along the magnified arc segment." },
  { n: 50, pos: 0.8, txt: "As the number of partitions n approaches infinity, the length of each segment approaches zero, and the sum converges to the exact line integral regardless of sample point placement." }
];
let currentStep = 0;

function applyStep(idx) {
  const s = demoSteps[idx];

  const elN = document.getElementById('numSegmentsInput');
  const elPos = document.getElementById('samplePosInput');

  if(elN) { elN.value = s.n; document.getElementById('numSegmentsVal').value = s.n; }
  if(elPos) { elPos.value = s.pos; document.getElementById('samplePosVal').value = s.pos; }

  n = s.n;
  samplePos = s.pos;

  const nar = document.getElementById('demoNarration');
  if(nar) {
    nar.innerText = s.txt;
    document.getElementById('stepLabel').innerText = `Step ${idx + 1}/3`;
    document.getElementById('btnPrev').disabled = (idx === 0);
    document.getElementById('btnNext').disabled = (idx === demoSteps.length - 1);
  }
  updateScene();
}

window.prevStep = function() { if (currentStep > 0) applyStep(--currentStep); };
window.nextStep = function() { if (currentStep < demoSteps.length - 1) applyStep(++currentStep); };

document.getElementById('demoPlayer').style.display = 'flex';
applyStep(0);

window.__markRendered();
// @FIGURE_CODE_END

