  for (let i = 0; i < insetPts.length; i++) {
    let p = insetPts[i];
    let pPrev = insetPts[Math.max(0, i - 1)];
    let pNext = insetPts[Math.min(insetPts.length - 1, i + 1)];
    if (i === 0) pPrev = p;
    if (i === insetPts.length - 1) pNext = p;
    let dx = pNext[0] - pPrev[0], dy = pNext[1] - pPrev[1];
    let dLen = Math.hypot(dx, dy);
    let nx = -dy / dLen, ny = dx / dLen;
    insetDimPts.push([p[0] + nx * 45, p[1] + ny * 45]);
  }
  drawDimensionArc(dynamicGroup, insetDimPts, '#555', 'Δsₖ');

  // 7. Dynamic Sample Point (P_k^*)
  let sLen = startL + samplePos * segLen;
  let sPointMain = mainCurveNode.getPointAtLength(sLen);
  let sInsetX = insetTargetX + (sPointMain.x - cX) * insetScale;
  let sInsetY = insetTargetY + (sPointMain.y - cY) * insetScale;

  dynamicGroup.circle(16).center(sInsetX, sInsetY).fill('#f23a2e');
  dynamicGroup.text('Pₖ*(xₖ*, yₖ*, zₖ*)')
    .font({ size: 18, family: 'serif', style: 'italic' })
    .move(sInsetX + 15, sInsetY + 15);

  // 8. Integration Convergence / Formula Box
  let totalSum = 0;
  for (let i = 0; i < n; i++) {
    let l = (i + samplePos) * segLen;
    let p = mainCurveNode.getPointAtLength(l);
    // Arbitrary background density function mapping roughly to (y) bounds
    let density = 1 + (600 - p.y) / 200;
    totalSum += density * segLen;
  }

  // Formula box container
  const boxGroup = dynamicGroup.group().move(80, 500);
  boxGroup.rect(340, 50).fill('#fff').stroke({ color: '#bbb', width: 2 }).radius(4);
  boxGroup.text('ΔMₖ ≈ f(xₖ*, yₖ*, zₖ*) Δsₖ')
    .font({ size: 20, family: 'serif', style: 'italic' })
    .center(170, 25);
  boxGroup.css('cursor', 'pointer')
    .on('mousemove', e => showTooltip('The mass of the k-th segment is estimated by multiplying the density at the sample point by the length of the sub-arc.', e))
    .on('mouseleave', hideTooltip);

  dynamicGroup.text(`Riemann Sum (Total Mass) ≈ ${totalSum.toFixed(1)}`)
    .font({ size: 18, family: 'sans-serif', weight: 'bold' })
    .center(250, 480)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4 });
}

