    const elN = document.getElementById('numSegmentsInput');
    const elPos = document.getElementById('samplePosInput');

    if(elN) { elN.value = s.n; document.getElementById('numSegmentsVal').value = s.n; }
    if(elPos) { elPos.value = s.pos; document.getElementById('samplePosVal').value = s.pos; }

    n = s.n;
    samplePos = s.pos;

    const nar = document.getElementById('demoNarration');
    if(nar) {
      nar.innerText = s.txt;
      document.getElementById('stepLabel').innerText = `Step ${idx + 1}/3`;
      document.getElementById('btnPrev').disabled = (idx === 0);
      document.getElementById('btnNext').disabled = (idx === demoSteps.length - 1);
