// @FIGURE_CODE_BEGIN
const W = 800, H = 600;
const draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

let n = 8;
let samplePos = 0.5;

// Main Curve definition: An open, unwinding spiral that matches the source topology 
// without self-intersecting. Starts bottom-left, gracefully forms a CCW loop, and exits top-right.
const pathStr = "M 60 480 C 180 400, 280 320, 280 200 C 280 80, 100 80, 100 200 C 100 280, 160 310, 200 300 C 260 280, 320 200, 380 100";
const mainCurveNode = document.createElementNS('http://www.w3.org/2000/svg', 'path');
mainCurveNode.setAttribute('d', pathStr);

// Add to defs to ensure getPointAtLength works seamlessly across browsers
const defs = draw.defs();
defs.node.appendChild(mainCurveNode);

// Let the DOM update so getTotalLength is guaranteed accurate
setTimeout(() => {
  const totalLen = mainCurveNode.getTotalLength();

  // Static background layer for the main curve
  const bgLayer = draw.group();
  bgLayer.path(pathStr).fill('none').stroke({ color: '#2ea3f2', width: 3 });

  const dynamicGroup = draw.group();

  // Helper to extract a sequence of points along a path segment
  function getSubPath(node, startL, endL, steps = 30) {
    let pts = [];
    for (let i = 0; i <= steps; i++) {
      let l = startL + (endL - startL) * (i / steps);
      let p = node.getPointAtLength(l);
      pts.push([p.x, p.y]);
    }
    return pts;
  }

  // Robust math text renderer with native SVG tspans for sub/superscripts
  function renderMath(group, str, x, y, options = {}) {
    str = str.replace(/\\Delta\s?/g, 'Δ').replace(/\\approx\s?/g, '≈');
    const txt = group.text(add => {
      let i = 0;
      while (i < str.length) {
        if (str[i] === '_') {
          let end = i + 1;
          if (str[i + 1] === '{') {
            end = str.indexOf('}', i + 1) + 1;
            add.tspan(str.slice(i + 2, end - 1)).attr({ 'baseline-shift': 'sub', 'font-size': '0.75em' });
          } else {
            end = i + 2;
            if (str[i + 1]) add.tspan(str[i + 1]).attr({ 'baseline-shift': 'sub', 'font-size': '0.75em' });
          }
          i = end;
        } else if (str[i] === '^') {
          let end = i + 1;
          if (str[i + 1] === '{') {
            end = str.indexOf('}', i + 1) + 1;
            add.tspan(str.slice(i + 2, end - 1)).attr({ 'baseline-shift': 'super', 'font-size': '0.75em' });
          } else {
            end = i + 2;
            if (str[i + 1]) add.tspan(str[i + 1]).attr({ 'baseline-shift': 'super', 'font-size': '0.75em' });
          }
          i = end;
        } else {
          add.tspan(str[i]);
          i++;
        }
      }
    });

    txt.font({ family: 'serif', style: 'italic', size: options.size || 16 })
       .center(x, y);

    if (options.weight) txt.font({ weight: options.weight });

    if (options.stroke) {
      txt.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
    }
    return txt;
  }

  // Helper to draw dimension arcs with perpendicular boundary lines
  function drawDimensionArc(group, pts, offset, color, labelStr, textOffset = { x: 0, y: 0 }) {
    let arcPts = [];
    for (let i = 0; i < pts.length; i++) {
      let p = pts[i];
      let pPrev = pts[Math.max(0, i - 1)];
      let pNext = pts[Math.min(pts.length - 1, i + 1)];
      if (i === 0) pPrev = p;
      if (i === pts.length - 1) pNext = p;

      let dx = pNext[0] - pPrev[0], dy = pNext[1] - pPrev[1];
      let dLen = Math.hypot(dx, dy) || 1;
      let nx = -dy / dLen, ny = dx / dLen;
      arcPts.push([p[0] + nx * offset, p[1] + ny * offset]);
    }

    group.polyline(arcPts.map(p => p.join(',')).join(' ')).fill('none').stroke({ color: color, width: 1.5 });

    // Arrowheads
    const p0 = arcPts[0], p1 = arcPts[1];
    const a0 = Math.atan2(p0[1] - p1[1], p0[0] - p1[0]) * 180 / Math.PI;
    group.polygon('0,0 -10,-4 -10,4').fill(color)
         .transform({ translateX: p0[0], translateY: p0[1], rotate: a0 });

    const pn = arcPts[arcPts.length - 1], pn1 = arcPts[arcPts.length - 2];
    const an = Math.atan2(pn[1] - pn1[1], pn[0] - pn1[0]) * 180 / Math.PI;
    group.polygon('0,0 -10,-4 -10,4').fill(color)
         .transform({ translateX: pn[0], translateY: pn[1], rotate: an });

    // Perpendicular boundary extension lines
    const eLen = Math.abs(offset) + 12; // Extend past the dimension arc
    const startCurveP = pts[0];
    const startNx = (arcPts[0][0] - startCurveP[0]) / Math.abs(offset);
    const startNy = (arcPts[0][1] - startCurveP[1]) / Math.abs(offset);

    group.line(startCurveP[0] + startNx * 4, startCurveP[1] + startNy * 4, 
               startCurveP[0] + startNx * eLen, startCurveP[1] + startNy * eLen)
         .stroke({ width: 1.5, color: '#222' });

    const endCurveP = pts[pts.length - 1];
    const endNx = (arcPts[arcPts.length - 1][0] - endCurveP[0]) / Math.abs(offset);
    const endNy = (arcPts[arcPts.length - 1][1] - endCurveP[1]) / Math.abs(offset);

    group.line(endCurveP[0] + endNx * 4, endCurveP[1] + endNy * 4, 
               endCurveP[0] + endNx * eLen, endCurveP[1] + endNy * eLen)
         .stroke({ width: 1.5, color: '#222' });

    const midIdx = Math.floor(arcPts.length / 2);
    const midP = arcPts[midIdx];
    renderMath(group, labelStr, midP[0] + textOffset.x, midP[1] + textOffset.y, { stroke: true, size: 18 });
  }

  function updateScene() {
    dynamicGroup.clear();

    let segLen = totalLen / n;

    // Dynamically find the partition segment best aligned with the bottom of the loop (x~160, y~300)
    let targetPt = { x: 160, y: 300 };
    let bestK = 1;
    let minDist = Infinity;
    for (let i = 1; i < n - 1; i++) {
      let l = (i + 0.5) * segLen;
      let p = mainCurveNode.getPointAtLength(l);
      let d = Math.hypot(p.x - targetPt.x, p.y - targetPt.y);
      if (d < minDist) { minDist = d; bestK = i; }
    }
    let k = Math.max(1, Math.min(n - 2, bestK));

    let startL = k * segLen;
    let endL = (k + 1) * segLen;

    // 1. Draw partition points and selected labels on the main curve
    for (let i = 0; i <= n; i++) {
      let l = i * segLen;
      let p = mainCurveNode.getPointAtLength(l);
      dynamicGroup.circle(n > 25 ? 5 : 9).center(p.x, p.y).fill('#2ea3f2');

      let label = '';
      if (i === 0) label = 'P = P_0';
      else if (i === n) label = 'Q = P_n';
      else if (i === k) label = 'P_{k-1}';
      else if (i === k + 1) label = 'P_k';
      else if (n <= 15 && (i === 1 || i === 2 || i === 3)) label = `P_${i}`;
      else if (i === n - 1 && n <= 15) label = 'P_{n-1}';

      if (label) {
        let offset = { x: 20, y: 20 }; // Default offset (down/right)
        if (i === 0) offset = { x: 0, y: 25 };
        if (i === n) offset = { x: 0, y: -25 };
        // Place k bounds safely outside the inside loop arc
        if (i === k) offset = { x: -25, y: 25 }; 
        if (i === k + 1) offset = { x: 25, y: 25 };

        renderMath(dynamicGroup, label, p.x + offset.x, p.y + offset.y, { stroke: true, size: 16 });
      }
    }

    // 2. Highlight k-th segment
    let kPathPts = getSubPath(mainCurveNode, startL, endL, 20);
    dynamicGroup.polyline(kPathPts.map(p => p.join(',')).join(' '))
      .fill('none').stroke({ color: '#1a75ff', width: 5 });

    // 3. Main curve dimension line for Δs_k
    // Negative offset draws it on the 'UP' side (inside the CCW loop)
    drawDimensionArc(dynamicGroup, kPathPts, -35, '#333', '\\Delta s_k', { x: 0, y: -20 });

    // 4. "Mass ΔM_k" label pointing to the main curve segment (Minimalist thin pointer)
    let midL = startL + segLen / 2;
    let midP = mainCurveNode.getPointAtLength(midL);

    let massTxtX = midP.x - 65, massTxtY = midP.y + 65;
    renderMath(dynamicGroup, 'Mass \\Delta M_k', massTxtX, massTxtY, { size: 18, stroke: true });

    let tx = massTxtX + 20, ty = massTxtY - 20;
    let mx = midP.x - 3, my = midP.y + 3;

    // Thin line curving directly from text to arc
    dynamicGroup.path(`M ${tx} ${ty} Q ${tx + 10} ${my + 15}, ${mx} ${my}`)
      .fill('none').stroke({ width: 1.5, color: '#444' });

    // Small minimalist arrowhead
    let aAngle = Math.atan2(my - (my + 15), mx - (tx + 10)) * 180 / Math.PI;
    dynamicGroup.polygon('0,0 -8,-4 -8,4').fill('#444')
      .transform({ translateX: mx, translateY: my, rotate: aAngle });

    // 5. Inset Segment (Magnified view)
    const insetPts = [];
    const insetStart = { x: 500, y: 430 }, insetEnd = { x: 740, y: 360 };
    const insetCx = 640, insetCy = 450; 

    for (let i = 0; i <= 30; i++) {
      let t = i / 30;
      let x = (1 - t) * (1 - t) * insetStart.x + 2 * (1 - t) * t * insetCx + t * t * insetEnd.x;
      let y = (1 - t) * (1 - t) * insetStart.y + 2 * (1 - t) * t * insetCy + t * t * insetEnd.y;
      insetPts.push([x, y]);
    }

    dynamicGroup.polyline(insetPts.map(p => p.join(',')).join(' '))
      .fill('none').stroke({ color: '#2ea3f2', width: 7 });

    dynamicGroup.circle(14).center(insetStart.x, insetStart.y).fill('#2ea3f2');
    dynamicGroup.circle(14).center(insetEnd.x, insetEnd.y).fill('#2ea3f2');

    renderMath(dynamicGroup, 'P_{k-1}', insetStart.x - 25, insetStart.y + 25, { size: 18 });
    renderMath(dynamicGroup, 'P_k', insetEnd.x + 25, insetEnd.y + 15, { size: 18 });

    // Inset dimension line (Negative offset puts it ABOVE the concave-up arc)
    drawDimensionArc(dynamicGroup, insetPts, -45, '#333', '\\Delta s_k', { x: 0, y: -25 });

    // 6. Solid Block Arrow mapping the sub-arc to the inset
    // Single filled path ensuring correct proportions and avoiding main curve overlap
    const arrowPath = "M 220 330 Q 350 340, 430 400 L 420 390 L 470 420 L 415 445 L 425 420 Q 340 370, 210 360 Z";
    dynamicGroup.path(arrowPath).fill('#fce8d5').stroke({ color: '#e0c4a8', width: 2, linejoin: 'round' });

    // 7. Dynamic Sample Point (P_k^*)
    let st = samplePos;
    let sX = (1 - st) * (1 - st) * insetStart.x + 2 * (1 - st) * st * insetCx + st * st * insetEnd.x;
    let sY = (1 - st) * (1 - st) * insetStart.y + 2 * (1 - st) * st * insetCy + st * st * insetEnd.y;

    dynamicGroup.circle(16).center(sX, sY).fill('#f23a2e');
    renderMath(dynamicGroup, 'P_k^*(x_k^*, y_k^*, z_k^*)', sX + 75, sY + 25, { size: 18, stroke: true });

    // 8. Riemann Sum Calculation & Formula Box
    let totalSum = 0;
    for (let i = 0; i < n; i++) {
      let l = (i + samplePos) * segLen;
      let p = mainCurveNode.getPointAtLength(l);
      let density = 1 + (500 - p.y) / 200; // Simulated density varying with y
      totalSum += density * segLen;
    }

    // Formula box using transform for robust positioning
    const boxGroup = dynamicGroup.group().transform({ translateX: 80, translateY: 510 });
    boxGroup.rect(340, 50).fill('#fff').stroke({ color: '#bbb', width: 2 }).radius(4);
    renderMath(boxGroup, "\\Delta M_k \\approx f(x_k^*, y_k^*, z_k^*) \\Delta s_k", 170, 25, { size: 20 });

    boxGroup.css('cursor', 'pointer')
      .on('mousemove', e => showTooltip('The mass of the k-th segment is estimated by evaluating the density function f at a sample point P_k^* and multiplying by the arc length Δs_k.', e))
      .on('mouseleave', hideTooltip);

    const rsBox = dynamicGroup.group().transform({ translateX: 450, translateY: 535 });
    renderMath(rsBox, `Riemann Sum \\approx ${totalSum.toFixed(1)}`, 160, 0, { size: 18, stroke: true, weight: 'bold' });
  }

  // --- Interactions & Player ---
  window.update_numSegments = function(v) {
    n = v;
    updateScene();
  };

  window.update_samplePos = function(v) {
    samplePos = v;
    updateScene();
  };

  const demoSteps = [
    { n: 8, pos: 0.5, txt: "The curve from P to Q is divided into n sub-arcs. We estimate the total mass by approximating the mass of each sub-arc and summing them." },
    { n: 8, pos: 0.8, txt: "Within each segment k, we pick a sample point to evaluate the density function. Slide the sample point position to see it move along the magnified arc segment." },
    { n: 50, pos: 0.8, txt: "As the number of partitions n approaches infinity, the length of each segment approaches zero, and the sum converges to the exact line integral regardless of sample point placement." }
  ];
  let currentStep = 0;

  function applyStep(idx) {
    const s = demoSteps[idx];
    const elN = document.getElementById('numSegmentsInput');
    const elPos = document.getElementById('samplePosInput');

    if(elN) { elN.value = s.n; document.getElementById('numSegmentsVal').value = s.n; }
    if(elPos) { elPos.value = s.pos; document.getElementById('samplePosVal').value = s.pos; }

    n = s.n;
    samplePos = s.pos;

    const nar = document.getElementById('demoNarration');
    if(nar) {
      nar.innerText = s.txt;
      document.getElementById('stepLabel').innerText = `Step ${idx + 1}/3`;
      document.getElementById('btnPrev').disabled = (idx === 0);
      document.getElementById('btnNext').disabled = (idx === demoSteps.length - 1);
    }
    updateScene();
  }

  window.prevStep = function() { if (currentStep > 0) applyStep(--currentStep); };
  window.nextStep = function() { if (currentStep < demoSteps.length - 1) applyStep(++currentStep); };

  document.getElementById('demoPlayer').style.display = 'flex';
  applyStep(0);

  window.__markRendered();
}, 50);
